/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `TRG_users_role_profiles_insert` AFTER INSERT ON `users` FOR EACH ROW BEGIN IF NEW.role = 'user' THEN INSERT IGNORE INTO dating_user_profiles (userId) VALUES (NEW.id); ELSEIF NEW.role = 'admin' THEN INSERT IGNORE INTO admin_profiles (userId) VALUES (NEW.id); ELSEIF NEW.role = 'super_admin' THEN INSERT IGNORE INTO super_admin_profiles (userId) VALUES (NEW.id); ELSEIF NEW.role = 'sales' THEN INSERT IGNORE INTO sales_profiles (userId) VALUES (NEW.id); ELSEIF NEW.role = 'support' THEN INSERT IGNORE INTO support_profiles (userId) VALUES (NEW.id); ELSEIF NEW.role = 'marketing' THEN INSERT IGNORE INTO marketing_profiles (userId) VALUES (NEW.id); END IF; END */;;
